#' Descriptives (Python)
#'
#' 
#' @param data .
#' @param vars .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$desc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$desc$asDF}
#'
#' \code{as.data.frame(results$desc)}
#'
#' @export
pydescriptives <- function(
    data,
    vars = NULL,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydescriptives requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- pydescriptivesOptions$new(
        vars = vars,
        showConsole = showConsole)

    analysis <- pydescriptivesClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

